package com.loadoutstudio;
import com.google.gson.*;
import java.util.*;import java.util.concurrent.*;
import javax.swing.*;
import net.runelite.http.api.RuneLiteAPI;
import org.junit.Test;
import static org.junit.Assert.*;
public class StudioDiagnosticsTest {
 @Test public void typedOutcomesExcludeMessagesAndSeparateBadInputFromBugs(){StudioDiagnostics d=new StudioDiagnostics();d.failure(StudioDiagnostics.Operation.IMPORT,new IllegalArgumentException("PRIVATE_INPUT_MARKER"),0);d.failure(StudioDiagnostics.Operation.SAVE,new IllegalStateException("PRIVATE_STATE_MARKER"),0);d.failure(StudioDiagnostics.Operation.WIKI_HTTP,new java.io.IOException("PRIVATE_URL_MARKER"),0);d.failure(StudioDiagnostics.Operation.UI_ACTION,new NullPointerException("PRIVATE_ERROR_MARKER"),0);String report=d.report("not/a/version");for(String secret:new String[]{"PRIVATE_INPUT_MARKER","PRIVATE_STATE_MARKER","PRIVATE_URL_MARKER","PRIVATE_ERROR_MARKER","not/a/version"})assertFalse(report.contains(secret));assertTrue(report.contains("VALIDATION=1"));assertTrue(report.contains("EXPECTED_STATE=1"));assertTrue(report.contains("IO_FAILURE=1"));assertTrue(report.contains("UNEXPECTED=1"));assertTrue(report.contains("RuneLite: unknown"));assertTrue(report.contains("StudioDiagnosticsTest.typedOutcomes"));}
 @Test public void recentOutcomesAreBoundedAndDisableAndResetClearTheSession(){StudioDiagnostics d=new StudioDiagnostics();for(int i=0;i<100;i++)d.completed(StudioDiagnostics.Operation.IMPORT,StudioDiagnostics.Outcome.VALIDATION,0);String report=d.report("1.13.3");String recent=report.substring(report.indexOf("Recent technical"));assertEquals(25,recent.lines().count());d.enabled(false);d.completed(StudioDiagnostics.Operation.SAVE,StudioDiagnostics.Outcome.SUCCESS,0);assertTrue(d.report("1.13.3").contains("No samples."));assertTrue(d.report("1.13.3").contains("Recording: disabled"));d.enabled(true);d.completed(StudioDiagnostics.Operation.SAVE,StudioDiagnostics.Outcome.SUCCESS,0);assertTrue(d.report("1.13.3").contains("SAVE: calls=1"));d.clear();assertTrue(d.report("1.13.3").contains("No samples."));}
 static class Host extends PanelTest.FakeHost {final StudioDiagnostics diagnostics=new StudioDiagnostics();boolean enabled=true;String copied;int issues;public StudioDiagnostics diagnostics(){return diagnostics;}public LoadoutStudioConfig settings(){return new LoadoutStudioConfig(){public boolean localDiagnostics(){return enabled;}};}public void copyText(String report){copied=report;}public void openIssuePage(){issues++;}public String diagnosticRuneLiteVersion(){return "1.13.3";}}
 @Test public void diagnosticViewIsReviewedBeforeCopyAndDoesNotOpenOrSendAnythingAutomatically()throws Exception{SwingUtilities.invokeAndWait(()->{Host h=new Host();StudioPanel p=new StudioPanel(h,RuneLiteAPI.GSON);JPanel controls=p.diagnosticControls();assertNull(h.copied);assertEquals(0,h.issues);String visible=((JTextArea)OwnedGearPanelTest.find(controls,"diagnosticReport")).getText();((JButton)OwnedGearPanelTest.find(controls,"Copy report")).doClick();assertEquals(visible,h.copied);assertEquals(0,h.issues);((JButton)OwnedGearPanelTest.find(controls,"Open GitHub issue")).doClick();assertEquals(1,h.issues);((JButton)OwnedGearPanelTest.find(controls,"Reset diagnostics")).doClick();assertTrue(((JTextArea)OwnedGearPanelTest.find(controls,"diagnosticReport")).getText().contains("No samples."));p.dispose();});}
 @Test public void featureCountersNeverIncludeSetupNotesOrExportContents()throws Exception{SwingUtilities.invokeAndWait(()->{Host h=new Host();StudioPanel p=new StudioPanel(h,RuneLiteAPI.GSON);JsonObject setup=SetupCodec.blank("PRIVATE_SETUP_MARKER");SetupCodec.setup(setup).addProperty("notes","PRIVATE_NOTE_MARKER");SetupCodec.setup(setup).getAsJsonArray("inv").set(0,SetupCodec.item(560,15000));SetupCodec.rebuildLayout(setup);p.newDraft(setup);OwnedGearPanelTest.click(p,"Save");OwnedGearPanelTest.click(p,"nav:Export");OwnedGearPanelTest.click(p,"Copy code");String report=p.diagnosticReport();assertTrue(report.contains("SAVE: calls=1"));assertTrue(report.contains("EXPORT_COPY: calls=1"));assertFalse(report.contains("PRIVATE_SETUP_MARKER"));assertFalse(report.contains("PRIVATE_NOTE_MARKER"));assertFalse(report.contains(h.copied));assertFalse(report.contains("15000"));p.dispose();});}
 @Test public void disablingRecordingFromSettingsStopsCollectionAndLeavesFeatureBehaviorIntact()throws Exception{SwingUtilities.invokeAndWait(()->{Host h=new Host();StudioPanel p=new StudioPanel(h,RuneLiteAPI.GSON);p.open(new SetupLibrary.Entry(SetupCodec.blank("Test")));OwnedGearPanelTest.click(p,"Save");assertTrue(p.diagnosticReport().contains("SAVE: calls=1"));h.enabled=false;p.preferencesChanged();OwnedGearPanelTest.click(p,"Save");assertNotNull(h.saved);assertTrue(p.diagnosticReport().contains("No samples."));assertTrue(OwnedGearPanelTest.find(p,"supportCoffee").isVisible());p.dispose();});}
 @Test public void wikiCacheAndHttpCountersDoNotAddTrafficOrRetainThePageTitle()throws Exception{java.util.concurrent.atomic.AtomicInteger requests=new java.util.concurrent.atomic.AtomicInteger();okhttp3.OkHttpClient http=new okhttp3.OkHttpClient.Builder().addInterceptor(chain->{requests.incrementAndGet();return new okhttp3.Response.Builder().request(chain.request()).protocol(okhttp3.Protocol.HTTP_1_1).code(200).message("OK").body(okhttp3.ResponseBody.create(okhttp3.MediaType.parse("application/json"),PersistentWikiTest.BODY)).build();}).build();WikiClient wiki=new WikiClient(http,RuneLiteAPI.GSON,0,new PersistentWikiTest.Store());StudioDiagnostics d=new StudioDiagnostics();wiki.diagnostics(d);try{assertEquals(0,requests.get());PersistentWikiTest.page(wiki,false);PersistentWikiTest.page(wiki,false);assertEquals(1,requests.get());String report=d.report("1.13.3");assertTrue(report.contains("WIKI_HTTP: calls=1"));assertTrue(report.contains("WIKI_CACHE_HIT: calls=1"));assertFalse(report.contains("Vorkath"));assertFalse(report.contains("https://oldschool"));}finally{wiki.close();http.dispatcher().executorService().shutdownNow();http.connectionPool().evictAll();}}
 @Test public void concurrentRecordingDoesNotLoseCalls()throws Exception{StudioDiagnostics d=new StudioDiagnostics();ExecutorService pool=Executors.newFixedThreadPool(4);try{List<CompletableFuture<Void>> jobs=new ArrayList<>();for(int i=0;i<1000;i++)jobs.add(CompletableFuture.runAsync(()->d.completed(StudioDiagnostics.Operation.WIKI_CACHE_HIT,StudioDiagnostics.Outcome.SUCCESS,0),pool));CompletableFuture.allOf(jobs.toArray(new CompletableFuture[0])).get(10,TimeUnit.SECONDS);assertTrue(d.report("1.13.3").contains("WIKI_CACHE_HIT: calls=1000"));}finally{pool.shutdownNow();}}
}
